{"type": "function", "function": {"name": "get_today_emails_until_now", "description": "Retrieves today's emails until now.", "parameters": {"type": "object", "properties": {}}, "return": {"type": "object", "description": "A dictionary containing the status and email records for the current day until now."}}}
{"type": "function", "function": {"name": "search_email_by_sender_and_receiver", "description": "Searches for emails where the sender or receiver contains specific address.", "parameters": {"type": "object", "properties": {"address": {"type": "string", "description": "Address to search for."}}, "required": ["address"]}, "return": {"type": "array", "items": {"type": "object"}, "description": "all emails matching the subject."}}}
{"type": "function", "function": {"name": "search_email_by_content", "description": "Searches for emails by the similarity of email's content and query using BM25.", "parameters": {"type": "object", "properties": {"query": {"type": "string", "description": "Query to search for."}}, "required": ["query"]}, "return": {"type": "array", "items": {"type": "object"}, "description": "List of the top 5 emails matching the query, sorted by BM25 score."}}}
{"type": "function", "function": {"name": "get_current_health_and_mood_status", "description": "Retrieves the current health and mood status of the user.", "parameters": {"type": "object", "properties": {}}, "return": {"type": "object", "description": "A dictionary containing the status and the most recent health and mood record before the specified timestamp."}}}
{"type": "function", "function": {"name": "get_user_recent_workout_records", "description": "Retrieves the most recent workout record after the specified timestamp until now.", "parameters": {"type": "object", "properties": {"time": {"type": "string", "description": "The timestamp after which to retrieve the workout record. The format should be '%Y-%m-%d %H:%M:%S', indicating the starting point of the time range for fetching records until now."}}, "required": ["time"]}, "return": {"type": "object", "description": "A dictionary containing the status of the operation and the most recent workout record."}}}
{"type": "function", "function": {"name": "get_recent_health_and_mood_summary", "description": "Retrieves the most recent health and mood records after the specified timestamp until now.", "parameters": {"type": "object", "properties": {"time": {"type": "string", "description": "The timestamp after which to retrieve the health and mood summary record. The format should be '%Y-%m-%d %H:%M:%S', indicating the starting point of the time range for fetching records until now."}}, "required": ["time"]}, "return": {"type": "object", "description": "A dictionary containing the status of the operation and the most recent health and mood records."}}}
{"type": "function", "function": {"name": "play_music", "description": "Plays a music track and records the playback operation.", "parameters": {"type": "object", "properties": {"music_name": {"type": "string", "description": "The name of the music track to play, excluding the artist's name."}, "volume_level": {"type": "integer", "description": "The volume level for playback (0-100), ranging from 0 (silent) to 100 (loudest)."}}, "required": ["music_name", "volume_level"]}, "return": {"type": "object", "description": "Status message indicating the result of the operation."}}}
