{"type": "function", "function": {"name": "add_product_to_cart", "description": "Adds a product to the cart.", "parameters": {"type": "object", "properties": {"product_id": {"type": "string", "description": "The unique identifier of the product."}, "product_name": {"type": "string", "description": "The name of the product."}, "quantity": {"type": "integer", "description": "The number of units of the product to add to the cart."}}, "required": ["product_id", "product_name", "quantity"]}, "return": {"type": "string", "description": "A message confirming the addition."}}}
{"type": "function", "function": {"name": "search_products_in_shopping_manager", "description": "Searches for products in the browsing history.", "parameters": {"type": "object", "properties": {"query": {"type": ["object", "string"], "description": "The name of the product to search for or a list of product names to search for."}}, "required": ["query"]}, "return": {"type": "object", "description": "A dictionary containing a status message and a list of matching products."}}}
{"type": "function", "function": {"name": "view_cart_in_shopping_manager", "description": "Views the current items in the cart.", "parameters": {"type": "object", "properties": {}}, "return": {"type": "object", "description": "A list containing items in the cart."}}}
{"type": "function", "function": {"name": "control_curtains_in_home", "description": "Controls the opening and closing of the curtains in home.", "parameters": {"type": "object", "properties": {"open": {"type": "string", "description": "True to open the curtains, False to close."}}, "required": ["open"]}, "return": {"type": "string", "description": "Status message."}}}
{"type": "function", "function": {"name": "control_bathtub_in_home", "description": "Controls the filling and temperature of the bathtub in home.", "parameters": {"type": "object", "properties": {"fill": {"type": "string", "description": "True to fill the bathtub, False to drain."}, "water_level": {"type": "number", "nullable": true, "description": "Desired water height level of the bathtub."}, "temperature": {"type": "number", "nullable": true, "description": "Desired water temperature in Celsius."}, "keep_temperature": {"type": "string", "description": "If True, keeps the water at the desired temperature."}}, "required": ["fill"]}, "return": {"type": "string", "description": "Status message."}}}
{"type": "function", "function": {"name": "boil_water_in_home", "description": "Boiling water in the kettle in home.", "parameters": {"type": "object", "properties": {"temperature": {"type": "number", "description": "Desired water temperature in Celsius(<100)."}, "keep_temperature": {"type": "string", "description": "If True, keeps the water at the desired temperature."}}, "required": ["temperature"]}, "return": {"type": "object", "description": "Status message."}}}
{"type": "function", "function": {"name": "control_light_in_home", "description": "Controls the light in the home by turning it on or off with specified settings.", "parameters": {"type": "object", "properties": {"action": {"type": "string", "description": "The action to perform ('on' or 'off')."}, "location": {"type": "string", "description": "The location of the light in the home ('residence', 'kitchen', 'dining room', 'living room', 'bedroom', 'bathroom')."}, "brightness": {"type": "integer", "description": "Brightness level (1-3). Required if action is 'on'."}, "color": {"type": "string", "description": "Color of the light ('yellow' or 'white'). Required if action is 'on'."}}, "required": ["action", "location"]}, "return": {"type": "object", "description": "A dictionary containing the status and a message about the light's state."}}}
